TIMELINE = [
 dict(year="1980", event="Late 1980: Penn's father Hugh Penn tells him the Zodiac used 'radian' in a suppressed July 1970 letter. On 26 Dec 1980 Penn lays a radian on the Mt. Diablo map (Blue Rock Springs - Mt. Diablo - Presidio Heights). Within days he presents a theory to Napa Sheriff Capt. Ken Narlow."),
 dict(year="1981", event="By January Penn has his 0/1 'digital transcription' of the 340 (nine-multiples class) and reads its opening 13 bits as the pi fraction = ERAHO. From January to May he mails anonymous postcards to O'Hare (the 'Rumplestiltskin Effect'), signing one with the pseudonym MIKE REVNEC, a Morse redivision of GARETH PENN."),
 dict(year="1981", event="May-July: a New West draft and the 'Zodiac Chrestomathy' go to the FBI. The FBI Lab (26 Jun 1981) notes 'Wizard' and 'Binary Morse' substitutions but finds the bulk 'speculation'. Penn adds a calendar analysis (24 Jun) and a telephone-number analysis (30 Jun). In November, as 'George Oakes' in California magazine, he publishes the radian, Morse-to-binary and the 390:18 = 130 pi proportion. Laube's Times-Herald profile quotes 'binary Morse ... and vice versa'."),
 dict(year="1981", event="November: 'Portrait of the Artist as a Mass Murderer', California magazine (formerly New West), pp.111-114, 166-170, as 'George Oakes' and rewritten by Tom Bates. It sets out the radian on Mt. Diablo, Morse-to-binary, the 390:18 pi proportion, WIZARD with 27-sum nulls (SLAVES -> HOZH), PHOMPHIT = H2O = MT/2PI, 4-TEEN, 'cid' = DCI = XEMIT, 144114 = 38 and the Tenniel source of the 1974 figures. On p.166 Penn cites Galileo's and Huygens's discoveries 'originally published as anagrams' (priority anagrams), alongside Jeremiah's atbash and Humphries's acrostic."),
 dict(year="1981-1987", event="Penn's series in The Ecphorizer (San Francisco Regional Mensa), 59 items from #2 (Oct 1981) to #62 (Jan 1987). The Zodiac pieces include '11.0010010000 11111101101' (#4, Dec 1981: radian, Z of postmarks, TREES = 320), 'Te Moriarty Salutamus' (#15: 340 binary, i-dot mm), 'Incline Village Unit 6' (#24: 1623 = MIKE O, permit timetable), 'One Zero Zero' (#29: crossed circle = 100, 13-cipher = MIKE O), 'The Pond of Kabbalah' and 'Sympathetic Magic at Goose Pond' (#36-37: 7120 ~ GOOSE, 4226 = BASIN), 'Thirty-Eight' (#41), 'Hide and Seek' (#46: the Grail Castle protocol), 'The Once and Future Killing' (#52: Bus Bomb geometry), 'Mike West' (#53: calls and Penn's own coded mailings), 'The Red King's Dream' (#56: chess on the call grid, 943 -> 349) and 'My Rosetta Stone' (#57: the 32-cipher). Wordplay pieces include 'More I-????-Its' (#8), 'Bumpersticker Bridge Goes Bananas' (#31: card-suit rebuses) and 'Creative Reading' (#50: reversed trademarks). Pen names in the series: Garfield Shaeffer, and '110011001010' (= G PENN)."),
 dict(year="1982", event="Penn builds the Zodiac Identification Kit (ZIK) and sends a 119-page packet to the FBI. The Lab (Jan 1983) calls the results 'forced and inconsistent'. He extends the theory to the Joan Webster disappearance in Boston (Nov 1981), using map angles at benchmarks."),
 dict(year="1983", event="'Times 17' talk at a Mensa regional gathering in Santa Rosa (May): GENEBERTA redivided as ZODIAC, and his claim that O'Hare's Social Security number gives Riverside's longitude. From June Penn mails encoded stimuli (Miami Card, New York Letter) and starts reading one-ring hang-up calls as replies."),
 dict(year="1984", event="The 'telephone literature' peaks. Penn tabulates calls in calendar grids (the 'Ten-Week Message', sum 38,838), plays clock-face hide-and-seek on the USGS Concord quadrangle, and has an X printed by the Lynn Item (28 Nov 1984). He sends the Honolulu Letter (two 35-cent stamps = BM x 2)."),
 dict(year="1985", event="Mensa Bulletin 'The Calculus of Evil' (Jul/Aug) gives A=1..Z=26 plus Morse 'convergence' (FRY/MERY -> ME 43), THREE = BUS = 'I am 130', 390:18 pi, the nine-multiples 340 key, and i-dot millimetre geometry (76/38 = TWO). Penn's 20 Aug circular adds 103 before MIKADO = MIKE, the 1623-letter count, ZODIAC = GENEBERTA and 13,880 = MH2O. The chess game is read off the call grid in Feb 1985, and the Bus Bomb Diagram geometry appears in The Ecphorizer (Dec)."),
 dict(year="1986", event="'The Radian Ciphers' (The Cryptogram, ACA, Nov-Dec) reads the 32- and 13-character ciphers by Morse of Roman letters only (57, 29, end-of-message). A Mensa Bulletin version is killed in December. Penn registers dated 'documents' with the Copyright Office."),
 dict(year="1987", event="Times 17 is published (Foxglove Press). It is the full toolkit: WIZARD, redivision, invisible geometry, telephone and calendar grids, the chess game, the 17x17 magic square summing to 9745, and 'A Zodiac Dictionary' (Appendix B)."),
 dict(year="1988-1990", event="Penn registers sealed, dated 'predictions' (for example 'Papers relating to the impending suicide of Michael Henry O'Hare on 17 May 1989', 'Zodiac calendars', '8790'). At the 1989 ACA convention a speaker ('YES') critiques Penn's 'solution'."),
 dict(year="1999", event="The Second Power: every Zodiac text is re-set 17 columns wide and digitized. Hidden redivisions are found by Word search. New readings include ONE-rectangles (area 60 = 'is'), right-triangle hypotenuses, character-per-day calendars, squares as 'masculine' and 17s as 'feminine', and a claimed hidden psycho-sexual autobiography. He compares O'Hare's own texts."),
 dict(year="2010", event="GZ4216 blog Q&A: JU.LY read with a binary point = 57.29, GUN = 22 x 9, three EIGHTs = 579, 13/17 = MHO, BLUE = BASE 2, 'two thirds', MIKE REVNEC admitted. Letter to Zam: BATES x KNIFE = #1030 and other 17-column intersection exhibits; his own puzzles are likened to Hooke's anagram. 'The Jig Is Up' parodies anagram and chain-of-association 'evidence' against Penn himself."),
 dict(year="2011", event="'Ave atque vale' (GZ4216 farewell): the positions of all 15 crossed circles; the first in each of three ciphers is a perfect square."),
 dict(year="2022", event="Private essays. 'The Zodiac literature: digital, multidimensional, nonverbal' covers taxicab numbers (YWHEN = 1729 at 10,11), sums of cubes, MAY = 219, &# = 7^3 and THE END = 2068 positions. 'The real puzzle' covers the 793-symbol consolidated cipher, the crossed-circle sum 1618 = phi, and the 340 dots (FIVE = 258, DEAD = 268). 'Radian' covers six RADIAN redivisions plus a fractional RAD (2 pi), TWO PI, expressive postmarks (7/31 = 43 x 17), cerium as a sqrt(58) triangle, 130PI and #408 as a sqrt(202) = MIKE triangle, and expressive differences."),
]
